import{_ as t,o as i,c as n,a4 as r}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0017 — Fichiers liés à une personne physique : adressage par identifiant, dépôt sans énumération","description":"Extrait de docs/adr/0017-fichiers-personnels-adresses-par-identifiant.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0017 — Fichiers liés à une personne physique : adressage par identifiant, dépôt sans énumération","description":"Extrait de docs/adr/0017-fichiers-personnels-adresses-par-identifiant.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0017-fichiers-personnels-adresses-par-identifiant.md","filePath":"developpeurs/adr/0017-fichiers-personnels-adresses-par-identifiant.md"}'),s={name:"developpeurs/adr/0017-fichiers-personnels-adresses-par-identifiant.md"};function a(o,e,d,c,u,l){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0017--fichiers-liés-à-une-personne-physique--adressage-par-identifiant-dépôt-sans-énumération" tabindex="-1">ADR-0017 — Fichiers liés à une personne physique : adressage par identifiant, dépôt sans énumération <a class="header-anchor" href="#adr-0017--fichiers-liés-à-une-personne-physique--adressage-par-identifiant-dépôt-sans-énumération" aria-label="Permalink to &quot;ADR-0017 — Fichiers liés à une personne physique : adressage par identifiant, dépôt sans énumération {#adr-0017--fichiers-liés-à-une-personne-physique--adressage-par-identifiant-dépôt-sans-énumération}&quot;">​</a></h1><p><strong>Date :</strong> 20 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §8.3 (règle élevée au rang de règle du Core) ; Epic E12</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC pose une exigence de sécurité et l&#39;élève explicitement au rang de <strong>règle du Core</strong> — c&#39;est-à-dire applicable à <em>tout</em> fichier lié à une personne physique, et pas seulement aux comptes usagers :</p><blockquote><p>Le stockage de fichier lié à une personne physique doit être accessible <strong>par ID via réécriture d&#39;URL, jamais par chemin ni nom de fichier</strong> ; le <strong>listing de dossier est interdit</strong>.</p></blockquote><p>Jusqu&#39;à l&#39;Epic E12, rien ne l&#39;implémentait : le champ <code>MediaFieldDef</code> (E1) référençait déjà un média par UUID, mais aucun stockage réel n&#39;était branché. L&#39;Epic E6 avait consigné la règle dans <code>app/rbac/__init__.py</code> en refusant de construire un service de fichiers par anticipation.</p><p>L&#39;Epic E12 crée le premier besoin réel : l&#39;<strong>archive ZIP d&#39;export RGPD</strong> d&#39;un compte usager (CDC §8.3) est la copie la plus complète qui existe des données personnelles d&#39;une personne. C&#39;est très exactement le fichier qui ne doit jamais être exposé par une URL devinable ni figurer dans un dossier listable. Une éventuelle photo de profil pose la même question à moindre enjeu.</p><p>La question à trancher n&#39;était donc pas <em>s&#39;il fallait</em> implémenter la règle, mais <strong>à quel niveau</strong> : un mécanisme spécifique aux comptes usagers, ou un mécanisme du Core réutilisable alors qu&#39;aucun autre usage n&#39;existe encore (ni médiathèque, ni pièces jointes de candidature).</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Un <strong>mécanisme du Core</strong>, <code>app/storage/personal_files.py</code>, adossé à une table <code>personal_files</code> au porteur polymorphe (<code>subject_kind</code> / <code>subject_id</code> : usager, agent, soumission de formulaire). L&#39;Epic E12 en est le premier client, pas le propriétaire.</p><p>Trois propriétés portent la règle, et chacune est <strong>structurelle</strong> plutôt que procédurale :</p><ol><li><p><strong>L&#39;identifiant public est un UUID v4 ; la clé de stockage en est une empreinte.</strong> <code>storage_key(organization_id, file_id)</code> rend <code>ab/cd/&lt;64 hexadécimaux&gt;</code> (SHA-256 des deux identifiants, découpé en deux niveaux). Le nom d&#39;origine ne participe <strong>pas</strong> au calcul : il n&#39;est qu&#39;une métadonnée rendue dans l&#39;en-tête <code>Content-Disposition</code>. La clé ne porte <strong>aucune extension</strong>, pour qu&#39;un serveur de fichiers statiques placé par erreur devant le dépôt ne sache pas quoi en faire, et pour que le type MIME servi vienne de la base plutôt que d&#39;un suffixe fourni par un déposant.</p></li><li><p><strong>Le protocole de dépôt n&#39;a pas de méthode d&#39;énumération.</strong> <code>PersonalFileStore</code> déclare <code>put</code>, <code>get</code>, <code>delete</code> — et rien d&#39;autre. Pas de <code>list()</code>, pas de <code>iterdir()</code>, pas de <code>glob()</code>. C&#39;est la traduction structurelle de « listing de dossier interdit » : aucune implémentation n&#39;a à en fournir un, et une implémentation qui en ajouterait une sortirait du protocole, ce qui se voit en relecture.</p></li><li><p><strong>La clé est validée avant tout accès disque.</strong> L&#39;implémentation sur système de fichiers refuse toute clé qui ne correspond pas exactement au motif produit par <code>storage_key</code>. Une traversée de répertoire (<code>../../etc/passwd</code>) n&#39;est donc pas <em>filtrée</em> : elle est <strong>inexprimable</strong>, parce qu&#39;elle ne ressemble pas à une empreinte.</p></li></ol><p>Côté HTTP, une <strong>seule</strong> route : <code>GET /api/v1/personal-files/{file_id}</code>, avec <code>file_id</code> typé <code>uuid.UUID</code> (un nom de fichier ou un chemin produit un 422 avant que le code de la route s&#39;exécute), l&#39;organisation lue dans la session et non dans la requête, et un <strong>404 unique</strong> pour « inconnu », « échu » et « pas à vous ». Il n&#39;existe aucune route de liste, aucun filtre par dossier, aucune recherche par nom.</p><p>La seule énumération existante — « quels fichiers appartiennent à cette personne ? », dont l&#39;export RGPD a besoin — passe par la base, bornée à un porteur nommé <strong>et</strong> à son organisation, et ne touche jamais le système de fichiers.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Un mécanisme spécifique aux comptes usagers</strong> (table <code>end_user_files</code>)</td><td>Moins de code aujourd&#39;hui, mais le CDC énonce la règle comme une règle du Core, et le prochain usage (médiathèque, pièces jointes de candidature) aurait construit son propre chemin — c&#39;est-à-dire une deuxième chance de se tromper sur une règle qui ne tolère pas d&#39;être tenue à moitié.</td></tr><tr><td><strong>Servir les fichiers par une URL signée à durée limitée</strong> (S3 presigned)</td><td>Reporte la protection sur un secret de signature à configurer, ce qui contredit « le Core démarre sans configuration » (CDC §14.11) ; et une URL signée reste une URL qui circule — historique de navigation, journal de proxy, partage de lien. Le contrôle par session est révocable, l&#39;URL signée ne l&#39;est pas (même raisonnement qu&#39;ADR-0008 sur le JWT).</td></tr><tr><td><strong>Une clé étrangère par type de porteur</strong> (<code>end_user_id</code>, <code>staff_user_id</code>, <code>submission_id</code> nullables)</td><td>Trois colonnes dont deux sont toujours nulles, et une quatrième à ajouter au prochain porteur. Même arbitrage que <code>page_access_rules.allowed_profiles</code> (E6) : une clé étrangère polymorphe est une colonne qui ne référence rien.</td></tr><tr><td><strong>Brancher S3/MinIO dans le Core</strong></td><td><code>settings.storage_endpoint</code> existe depuis le Sprint 0, mais y parler demanderait un client objet et une gestion d&#39;identifiants. Même arbitrage que le client SAML (E6) et l&#39;échangeur OIDC (E12) : le mécanisme au Core, l&#39;intégration au déploiement (<code>install_personal_file_store</code>). <em>(23/09/2026 : l&#39;échangeur OIDC a depuis été livré avec le Core, inactif, activé par <code>OIDC_ALLOWED_ISSUER_HOSTS</code> — <a href="/teuthis-cms-distribution/developpeurs/adr/0040-echangeur-oidc-des-usagers-livre-inactif">ADR-0040</a>. L&#39;arbitrage reste valable pour le stockage objet.)</em> Le captcha et le courriel, eux, ont fini par être livrés avec le Core — inactifs, activés par un réglage (ADR-0027) — parce qu&#39;une clé secrète suffit à les brancher, là où un client objet demande des identifiants, un compartiment et une rotation.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>La règle du CDC est tenue par la <strong>forme du code</strong> et non par la vigilance de chaque appelant : trois verrous à trois niveaux, chacun vérifié par un test de recette.</li><li>Le prochain Epic qui branchera un stockage (médiathèque, offres d&#39;emploi) trouve le mécanisme déjà là ; il n&#39;a ni route ni convention de nommage à réinventer.</li><li>Un nom de pièce jointe — souvent lui-même une donnée personnelle, du type <code>CV_Marie_Dupont_1987.pdf</code> — n&#39;apparaît dans aucune URL, aucun journal d&#39;accès HTTP, aucun référent.</li><li>Une installation neuve sait honorer un export RGPD sans configuration : le dépôt par défaut est un répertoire local et n&#39;appelle rien à l&#39;extérieur.</li></ul><p><strong>Négatives</strong></p><ul><li>Le porteur polymorphe ne cascade pas : c&#39;est le code qui efface les fichiers d&#39;une personne supprimée (<code>delete_files_of_subject</code>, appelé par le balayage du cycle de vie et par le droit à l&#39;effacement). Un futur porteur qui oublierait cet appel laisserait des fichiers orphelins — le prix explicite de la généricité, à rappeler dans la revue de tout nouvel usage.</li><li>L&#39;archive d&#39;export est construite et servie en mémoire. C&#39;est adapté à un compte usager (quelques kilo-octets) et <strong>ne l&#39;est pas</strong> à une médiathèque de fichiers lourds : celle-là devra introduire une remise en flux, sans changer l&#39;adressage.</li><li>Le répertoire de dépôt ne doit jamais être placé sous une racine servie par un serveur web. La règle est écrite dans <code>app/core/config.py</code>, à côté du réglage — c&#39;est une contrainte d&#39;exploitation que le code ne peut pas vérifier.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Mécanisme du Core (<code>app/storage/personal_files.py</code>) et route de réécriture d&#39;URL (<code>app/api/personal_files.py</code>) — Epic E12, migration <code>0012</code>.</li><li>[x] Premier usage : l&#39;archive ZIP + CSV de l&#39;export RGPD du compte usager (CDC §8.3), avec échéance paramétrable par organisation.</li><li>[x] Recette : <code>test_un_fichier_lie_a_une_personne_ne_s_atteint_que_par_son_id</code> (<code>apps/api/tests/test_end_users.py</code>) vérifie les cinq niveaux — protocole sans énumération, clé sans nom de fichier, refus des chemins, absence de route de liste, étanchéité entre deux personnes.</li><li>[x] Épic médiathèque : réutiliser ce mécanisme pour les fichiers liés à une personne, et <strong>seulement</strong> pour ceux-là — une photo d&#39;illustration d&#39;article n&#39;est liée à personne et relève d&#39;un stockage ordinaire. → <em>23/09/2026 : close par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a>.</em> La médiathèque ne passe pas par <code>personal_files</code> : ses octets vivent dans un dépôt distinct (<code>app/storage/media_files.py</code>, racine <code>MEDIA_ROOT</code>, que le démarrage refuse de confondre avec <code>PERSONAL_FILE_ROOT</code>), qui reprend la clé dérivée et l&#39;absence d&#39;énumération et relit en flux ; recette <code>apps/api/tests/test_mediatheque.py</code>.</li><li>[x] Épic offres d&#39;emploi : les pièces jointes de candidature passent par ce mécanisme. (Rappel : aucun scoring ni classement automatique de candidatures, CDC §14.7 / AI Act.) → <em>19/09/2026 : close par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0038-pieces-jointes-des-formulaires-publics">ADR-0038</a>.</em> Dépôt public <code>POST /public/forms/{clé}/attachments</code> sous le porteur d&#39;attente <code>pending_upload</code>, rattachement vérifié au porteur <code>form_submission</code>, lecture par un agent depuis le dossier ; recette <code>apps/api/tests/test_pieces_jointes.py</code>. Elle vaut pour les quatre formulaires publics qui déclarent un fichier, pas seulement pour le pack emploi.</li></ul>',23)])])}const g=t(s,[["render",a]]);export{m as __pageData,g as default};
